@import "tailwindcss";

html {
  scroll-behavior: smooth;
  color-scheme: light;
}

body {
  margin: 0;
  background: var(--background);
  color: var(--foreground);
  font-family: var(--font-dm-sans), Arial, Helvetica, sans-serif;
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-secondary: var(--secondary);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-border: var(--border);
  --font-sans: var(--font-dm-sans);
  --font-mono: var(--font-geist-mono);
  --font-display: var(--font-bricolage);
}

* {
  box-sizing: border-box;
}

body::selection {
  background: color-mix(in srgb, var(--accent) 22%, transparent);
  color: var(--foreground);
}

.psp-theme-root,
.psp-shell {
  font-family: var(--psp-font-ui), sans-serif;
}

.psp-shell {
  background:
    radial-gradient(circle at 76% 18%, color-mix(in srgb, var(--psp-accent) 8%, transparent), transparent 28%),
    var(--psp-bg);
  color: var(--psp-fg);
}

.psp-theme-root {
  min-height: 100vh;
  background: var(--psp-bg);
}

.psp-browse-shell {
  background: var(--psp-bg);

  /* A single responsive coordinate system for the header, XMB rail and
     preview. The right column follows the measured width of the left one. */
  --psp-edge: clamp(2rem, 6vw, 6.5rem);
  --psp-header-top: clamp(1.75rem, 5vh, 3.5rem);
  --psp-header-safe-bottom: calc(var(--psp-header-top) + 7.25rem);
  /* Focus header sits a little closer to the fixed name and social links. */
  --psp-focus-top: calc(var(--psp-header-safe-bottom) - 1rem);
  --psp-axis-top: clamp(12rem, 30dvh, 20rem);
  --psp-navigation-left: max(9.5rem, 15.5vw, calc(50% - 35rem));
  --psp-navigation-width: clamp(14.5rem, 22vw, 20rem);
  --psp-column-gap: clamp(3rem, 5vw, 5.5rem);
  --psp-details-left: calc(var(--psp-navigation-left) + var(--psp-navigation-width) + var(--psp-column-gap));
  --psp-row-offset: 7.875rem;
  --psp-rail-bottom: 3.75rem;
}

.psp-xmb-header {
  left: var(--psp-edge);
  right: var(--psp-edge);
  top: var(--psp-header-top);
}

.psp-xmb-group {
  left: var(--psp-navigation-left);
  width: var(--psp-navigation-width);
}

/* The very same preview panel expands into focus mode.
   Animate its geometry rather than swapping in an overlay. */
.psp-xmb-details {
  top: calc(var(--psp-axis-top) + var(--psp-row-offset));
  bottom: clamp(3.5rem, 8vh, 6rem);
  left: var(--psp-details-left);
  right: var(--psp-edge);
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: color-mix(in srgb, white 22%, transparent) transparent;
  transition:
    top 240ms cubic-bezier(.2,.75,.3,1),
    left 240ms cubic-bezier(.2,.75,.3,1),
    right 240ms cubic-bezier(.2,.75,.3,1),
    bottom 240ms cubic-bezier(.2,.75,.3,1);
}

.psp-xmb-details--expanded {
  top: var(--psp-focus-top);
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 25;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.psp-focus-toolbar {
  display: flex;
  flex: none;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
  height: 0;
  overflow: hidden;
  padding: 0 var(--psp-edge);
  border-bottom: 1px solid transparent;
  color: rgb(255 255 255 / 0.4);
  font-size: .75rem;
  text-transform: uppercase;
  letter-spacing: .18em;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition:
    height 240ms cubic-bezier(.2,.75,.3,1),
    padding 240ms cubic-bezier(.2,.75,.3,1),
    opacity 100ms ease,
    border-color 100ms ease;
}

.psp-focus-toolbar--visible {
  height: 3.5rem;
  padding: .65rem var(--psp-edge);
  border-bottom-color: rgb(255 255 255 / 0.1);
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
}

.psp-detail-scroll {
  min-height: 0;
}

.psp-xmb-details--expanded .psp-detail-scroll {
  flex: 1;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: color-mix(in srgb, white 20%, transparent) transparent;
  -webkit-overflow-scrolling: touch;
}

/* Writing alone becomes a full-height reading surface. The initial scroll
   padding preserves the focus layout; as it scrolls away, text can rise
   through the opening in the divider and reach the top of the viewport. */
.psp-xmb-details--expanded.psp-xmb-details--writing {
  top: 0;
}

.psp-xmb-details--writing .psp-detail-scroll {
  padding-top: 0;
  transition: padding-top 240ms cubic-bezier(.2, .75, .3, 1);
}

.psp-xmb-details--expanded.psp-xmb-details--writing .psp-detail-scroll {
  padding-top: calc(var(--psp-focus-top) + 3.5rem);
}

.psp-xmb-details--expanded.psp-xmb-details--writing .psp-focus-toolbar {
  position: absolute;
  inset-inline: 0;
  top: var(--psp-focus-top);
  z-index: 2;
  border-bottom-color: transparent;
  pointer-events: none;
}

.psp-xmb-details--writing .psp-focus-toolbar button {
  pointer-events: auto;
}

.psp-writing-divider {
  position: absolute;
  inset-inline: 0;
  bottom: 0;
  height: 1px;
  pointer-events: none;
}

.psp-writing-divider__half {
  position: absolute;
  top: 0;
  height: 1px;
  width: 50%;
  background: rgb(255 255 255 / .1);
}

.psp-writing-divider__half--left {
  left: 0;
  transform-origin: left center;
}

.psp-writing-divider__half--right {
  right: 0;
  transform-origin: right center;
}

.psp-xmb-detail-layout {
  max-width: 36rem;
  margin-left: 0;
  padding: 0;
  transition:
    padding 240ms cubic-bezier(.2,.75,.3,1),
    margin-left 240ms cubic-bezier(.2,.75,.3,1);
}

.psp-xmb-detail-inner {
  min-width: 0;
  border-left: 1px solid rgb(255 255 255 / 0.15);
  padding-left: clamp(1.5rem, 2.5vw, 2rem);
  transition: padding-left 240ms cubic-bezier(.2,.75,.3,1);
}

.psp-xmb-detail-layout--expanded {
  width: 100%;
  max-width: 94rem;
  margin: 0 auto;
  padding: clamp(1.5rem, 4vh, 2.5rem) var(--psp-edge) 6rem;
}

.psp-xmb-detail-layout--expanded .psp-xmb-detail-inner {
  border-left: 0;
  padding-left: 0;
}

.psp-xmb-detail-layout--writing.psp-xmb-detail-layout--expanded {
  max-width: 52rem;
  margin-left: max(0px, calc((100vw - 52rem) / 2));
  margin-right: 0;
}

.psp-xmb-detail-layout--gallery {
  display: grid;
  align-items: start;
  grid-template-columns: minmax(0, .95fr) minmax(0, 1.05fr);
  gap: clamp(2rem, 5vw, 5rem);
}

.psp-detail-gallery {
  position: sticky;
  top: 1rem;
  align-self: start;
}

.psp-detail-title {
  margin-top: .6rem;
  font-size: 1.5rem;
  transition: font-size 240ms cubic-bezier(.2,.75,.3,1);
}

.psp-xmb-details--expanded .psp-detail-title {
  font-size: clamp(2.25rem, 3.8vw, 3.75rem);
  line-height: 1.1;
}

.psp-detail-description {
  margin-top: .85rem;
  font-size: .875rem;
  line-height: 1.55rem;
  display: -webkit-box;
  -webkit-line-clamp: 4;
  -webkit-box-orient: vertical;
  overflow: hidden;
  transition: font-size 240ms cubic-bezier(.2,.75,.3,1);
}

.psp-xmb-details--expanded .psp-detail-description {
  display: block;
  overflow: visible;
  font-size: 1.125rem;
  line-height: 1.85rem;
  max-width: 46rem;
  color: rgb(255 255 255 / 0.72);
}

.psp-detail-note {
  margin-top: .85rem;
}

.psp-detail-open {
  display: block;
  width: fit-content;
  margin-top: 1.15rem;
}

.psp-detail-extra {
  min-width: 0;
}

@media (prefers-reduced-motion: reduce) {
  .psp-xmb-details,
  .psp-xmb-detail-layout,
  .psp-xmb-detail-inner,
  .psp-focus-toolbar,
  .psp-xmb-details--writing .psp-detail-scroll,
  .psp-detail-title,
  .psp-detail-description {
    transition: none;
  }
}

/* Keep the desktop XMB usable in a narrower browser window instead of
   squeezing the original wide-screen column offsets. */
@media (min-width: 1024px) and (max-width: 1279px) {
  .psp-browse-shell {
    --psp-edge: clamp(2.5rem, 5vw, 4rem);
    --psp-navigation-left: clamp(8.75rem, 14.5vw, 12rem);
    --psp-navigation-width: clamp(13.5rem, 22vw, 17.5rem);
    --psp-column-gap: clamp(2.5rem, 4vw, 3.25rem);
  }
}

.psp-xmb-category {
  transition: left 110ms linear, color 110ms linear;
}

.psp-xmb-item {
  transition: top 110ms linear, color 110ms linear;
}

.psp-xmb-rail {
  /* Unlike a z-index overlay, clipping also excludes hidden rail entries
     from mouse hit testing around the header. */
  clip-path: inset(var(--psp-header-safe-bottom) 0 0 0);
}

@media (prefers-reduced-motion: reduce) {
  .psp-xmb-category,
  .psp-xmb-item {
    transition: none;
  }
}

components/psp/psp-portfolio-page.tsx.text:
"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import { AnimatePresence, MotionConfig, motion } from "framer-motion";
import type {
  PortfolioWork,
  PortfolioHero,
  PortfolioContact,
  PortfolioExperience,
  PortfolioPost,
  PortfolioCollection,
} from "@/lib/portfolio-types";
import { buildXmbCategories } from "./psp-config";
import { XmbHeader } from "./xmb-header";
import { XmbHorizontalAxis } from "./xmb-horizontal-axis";
import { XmbVerticalAxis } from "./xmb-vertical-axis";
import { XmbDetailPanel } from "./xmb-detail-panel";
import { PspMobileView } from "./psp-mobile-view";
import { XmbExpandedDetail } from "./xmb-expanded-detail";
import { getPspThemeStyle } from "./psp-showcase-style";
import type { XmbItem } from "./types";
import { NEUTRAL_SHOWCASE } from "@/lib/showcase";

interface PspPortfolioPageProps {
  workItems: PortfolioWork[];
  hero: PortfolioHero;
  contact: PortfolioContact;
  experienceItems: PortfolioExperience[];
  posts: PortfolioPost[];
  collections: PortfolioCollection[];
}

export function PspPortfolioPage({
  workItems,
  hero,
  contact,
  experienceItems,
  posts,
  collections,
}: PspPortfolioPageProps) {
  const [expandedItem, setExpandedItem] = useState<XmbItem | null>(null);

  const categories = useMemo(
    () => buildXmbCategories({
      hero,
      workItems,
      experienceItems,
      posts,
      collections,
    }),
    [hero, workItems, experienceItems, posts, collections]
  );

  const [activeCategoryIndex, setActiveCategoryIndex] = useState(0);
  const [activeItemIndices, setActiveItemIndices] = useState<Record<number, number>>(
    () => Object.fromEntries(categories.map((_, i) => [i, 0]))
  );

  const activeCategory = categories[activeCategoryIndex] ?? categories[0];
  const activeItemIndex = activeItemIndices[activeCategoryIndex] ?? 0;
  const activeItem = activeCategory?.items?.[activeItemIndex];
  const categoryItemsLength = activeCategory?.items?.length ?? 0;

  const selectCategory = useCallback((index: number) => {
    setActiveCategoryIndex(index);
  }, []);

  const selectItem = useCallback((index: number) => {
    setActiveItemIndices((previous) => ({ ...previous, [activeCategoryIndex]: index }));
  }, [activeCategoryIndex]);

  const activateItem = useCallback((item?: XmbItem) => {
    if (!item) return;

    if (item.detailHref) {
      // An in-place history entry lets browser Back restore the browse state.
      window.history.pushState(
        { ...window.history.state, __portfolioFocusItem: item.id },
        "",
        window.location.href,
      );
      setExpandedItem(item);
      return;
    }

    if (item.href && item.href !== "#") {
      if (item.downloadName) {
        const link = document.createElement("a");
        link.href = item.href;
        link.download = item.downloadName;
        link.target = "_blank";
        link.rel = "noopener noreferrer";
        link.click();
        return;
      }

      if (item.href.startsWith("mailto:")) {
        window.location.href = item.href;
      } else {
        window.open(item.href, "_blank", "noopener,noreferrer");
      }
    }
  }, [activeCategoryIndex]);

  const activateItemAtIndex = useCallback((index: number) => {
    activateItem(activeCategory?.items[index]);
  }, [activateItem, activeCategory]);

  const closeExpandedItem = useCallback(() => {
    if (expandedItem && window.history.state?.__portfolioFocusItem === expandedItem.id) {
      window.history.back();
    } else {
      setExpandedItem(null);
    }
  }, [expandedItem]);

  const handleKeyDown = useCallback(
    (event: KeyboardEvent) => {
      if (expandedItem) {
        if (event.key === "Escape") {
          event.preventDefault();
          closeExpandedItem();
        }
        return;
      }

      // Let focused social links handle Enter and arrow keys normally.
      if (event.target instanceof HTMLElement && event.target.closest("a")) return;

      const navKeys = ["ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight", "Enter"];
      if (!navKeys.includes(event.key)) return;
      event.preventDefault();

      if (event.key === "ArrowLeft") {
        setActiveCategoryIndex((previous) => Math.max(0, previous - 1));
      } else if (event.key === "ArrowRight") {
        setActiveCategoryIndex((previous) => Math.min(categories.length - 1, previous + 1));
      } else if (event.key === "ArrowUp") {
        setActiveItemIndices((previous) => ({
          ...previous,
          [activeCategoryIndex]: Math.max(0, (previous[activeCategoryIndex] ?? 0) - 1),
        }));
      } else if (event.key === "ArrowDown") {
        setActiveItemIndices((previous) => ({
          ...previous,
          [activeCategoryIndex]: Math.min(
            Math.max(0, categoryItemsLength - 1),
            (previous[activeCategoryIndex] ?? 0) + 1
          ),
        }));
      } else if (event.key === "Enter") {
        activateItem(activeItem);
      }
    },
    [activeCategoryIndex, categoryItemsLength, activeItem, categories.length, activateItem, expandedItem, closeExpandedItem]
  );

  useEffect(() => {
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [handleKeyDown]);

  useEffect(() => {
    const onPopState = () => {
      const id = window.history.state?.__portfolioFocusItem;
      const categoryIndex = categories.findIndex((category) => category.items.some((item) => item.id === id));
      if (categoryIndex < 0) {
        setExpandedItem(null);
        return;
      }
      const items = categories[categoryIndex].items;
      const itemIndex = items.findIndex((item) => item.id === id);
      setActiveCategoryIndex(categoryIndex);
      setActiveItemIndices((previous) => ({ ...previous, [categoryIndex]: itemIndex }));
      setExpandedItem(items[itemIndex]);
    };
    window.addEventListener("popstate", onPopState);
    return () => window.removeEventListener("popstate", onPopState);
  }, [categories]);

  useEffect(() => {
    if (!expandedItem) return;
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      document.body.style.overflow = previousOverflow;
    };
  }, [expandedItem]);

  const siteName = [hero.firstName, hero.lastName].filter(Boolean).join(" ");
  const focusOpen = expandedItem !== null;
  const foldingTransition = { duration: 0.24, ease: [0.2, 0.75, 0.3, 1] as const };

  const themeStyle = {
    ...getPspThemeStyle(activeItem?.showcase),
    ["--psp-bg" as string]: NEUTRAL_SHOWCASE.backgroundColor,
  };

  return (
    <MotionConfig reducedMotion="user">
      <div className="psp-theme-root" style={themeStyle}>
        <div className="block lg:hidden">
          <div inert={focusOpen} aria-hidden={focusOpen}>
            <PspMobileView
              categories={categories}
              contact={contact}
              name={siteName}
              activeCategoryIndex={activeCategoryIndex}
              activeItemIndex={activeItemIndex}
              onCategorySelect={selectCategory}
              onItemSelect={selectItem}
              onItemActivate={activateItemAtIndex}
            />
          </div>
          <AnimatePresence initial={false}>
            {expandedItem && (
              <XmbExpandedDetail
                key={expandedItem.id}
                item={expandedItem}
                variant="mobile"
                siteName={siteName}
                onClose={closeExpandedItem}
              />
            )}
          </AnimatePresence>
        </div>

        <div className="psp-shell psp-browse-shell fixed inset-0 z-40 hidden select-none overflow-hidden text-white lg:block">
          <XmbHeader name={siteName} contact={contact} />

          <motion.div
            className="pointer-events-none absolute inset-0 z-10"
            inert={focusOpen}
            aria-hidden={focusOpen}
            animate={{ y: focusOpen ? -65 : 0, opacity: focusOpen ? 0 : 1 }}
            transition={foldingTransition}
            style={{ pointerEvents: focusOpen ? "none" : "auto" }}
          >
            <XmbHorizontalAxis
              categories={categories}
              activeCategoryIndex={activeCategoryIndex}
              onCategorySelect={selectCategory}
            />
          </motion.div>

          <motion.div
            className="absolute inset-0 z-10"
            inert={focusOpen}
            aria-hidden={focusOpen}
            animate={{ y: focusOpen ? -110 : 0, opacity: focusOpen ? 0 : 1 }}
            transition={foldingTransition}
            style={{ pointerEvents: focusOpen ? "none" : "auto" }}
          >
            <XmbVerticalAxis
              items={activeCategory.items}
              activeItemIndex={activeItemIndex}
              onItemSelect={selectItem}
              onItemActivate={activateItemAtIndex}
            />
          </motion.div>

          <XmbDetailPanel
            activeItem={activeItem}
            onActivate={activeItem?.activationLabel ? () => activateItem(activeItem) : undefined}
            expanded={focusOpen}
            onClose={closeExpandedItem}
          />

          <motion.p
            aria-hidden={focusOpen}
            className="pointer-events-none absolute bottom-8 right-[var(--psp-edge)] z-10 text-xs text-white/35"
            animate={{ opacity: focusOpen ? 0 : 1 }}
            transition={{ duration: 0.2 }}
          >
            Arrow keys to browse · Enter to open
          </motion.p>

          <p className="sr-only" aria-live="polite">
            {expandedItem ? `Open: ${expandedItem.title}` : `${activeCategory.label}: ${activeItem?.title}`}
          </p>
        </div>
      </div>
    </MotionConfig>
  );
}

components/psp/xmb-detail-panel.tsx.text:
"use client";

import { useEffect, useRef } from "react";
import { AnimatePresence, motion, useReducedMotion, useScroll, useTransform } from "framer-motion";
import type { XmbItem } from "./types";
import { MarkdownText } from "./markdown-text";
import { ProjectGallery } from "./project-gallery";

interface XmbDetailPanelProps {
  activeItem?: XmbItem;
  onActivate?: () => void;
  expanded?: boolean;
  onClose?: () => void;
}

export function XmbDetailPanel({
  activeItem,
  onActivate,
  expanded = false,
  onClose,
}: XmbDetailPanelProps) {
  const backRef = useRef<HTMLButtonElement>(null);
  const openRef = useRef<HTMLButtonElement>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const wasFocusedRef = useRef(false);
  const reducedMotion = useReducedMotion();
  const isProject = activeItem?.kind === "project";
  const isPost = activeItem?.kind === "post";
  const focused = expanded && (isProject || isPost);
  const writingFocused = focused && isPost;
  // Scroll drives both divider halves directly, without duration or easing.
  const { scrollY } = useScroll({ container: scrollRef });
  // The date is only ~2rem below the divider at rest, so open almost fully
  // before it reaches the line rather than stretching the split over 180px.
  const dividerScale = useTransform(scrollY, [0, 14, 30], [1, 0.25, 0.06]);
  const animation = { duration: reducedMotion ? 0 : 0.14, ease: "easeOut" as const };

  useEffect(() => {
    if (focused) backRef.current?.focus();
    else if (wasFocusedRef.current) openRef.current?.focus();
    wasFocusedRef.current = focused;
  }, [focused]);

  useEffect(() => {
    // The preview and full article share the scroll element. Start each reading
    // session at its beginning instead of inheriting the previous position.
    if (writingFocused && scrollRef.current) scrollRef.current.scrollTop = 0;
  }, [writingFocused, activeItem?.id]);

  // Keep the exact same heading and description mounted in both modes.
  // Only the panel's geometry changes; the full body/gallery are added around it.
  const images = activeItem && isProject
    ? Array.from(new Set(
        [activeItem.showcase?.artworkUrl, activeItem.image, ...(activeItem.gallery ?? [])]
          .filter((src): src is string => Boolean(src))
      ))
    : [];
  const links = activeItem && isProject ? [
    ...(activeItem.links ?? []),
    ...(activeItem.href && activeItem.href !== "#" &&
      !activeItem.links?.some((link) => link.url === activeItem.href)
      ? [{ label: "Open project", url: activeItem.href }]
      : []),
  ] : [];

  return (
    <section
      className={`psp-xmb-details absolute z-20 ${focused ? "psp-xmb-details--expanded" : ""} ${isPost ? "psp-xmb-details--writing" : ""}`}
      aria-label={focused ? (isPost ? "Writing focus view" : "Project focus view") : "Selected item details"}
    >
      <div
        className={`psp-focus-toolbar ${focused ? "psp-focus-toolbar--visible" : ""}`}
        aria-hidden={!focused}
        inert={!focused}
      >
        <span>{isPost ? "Writing" : "Projects"}</span>
        <button
          ref={backRef}
          type="button"
          onClick={onClose}
          className="rounded-sm px-2 py-1.5 text-sm normal-case tracking-normal text-white/70 hover:text-white focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--psp-accent)]"
        >
          ← Back <span className="ml-2 text-xs text-white/30">Esc</span>
        </button>
        {writingFocused && (
          <div className="psp-writing-divider" aria-hidden="true">
            <motion.span
              className="psp-writing-divider__half psp-writing-divider__half--left"
              style={{ scaleX: reducedMotion ? 0 : dividerScale }}
            />
            <motion.span
              className="psp-writing-divider__half psp-writing-divider__half--right"
              style={{ scaleX: reducedMotion ? 0 : dividerScale }}
            />
          </div>
        )}
      </div>

      <div ref={scrollRef} className="psp-detail-scroll">
        {activeItem && (
          <div
            className={`psp-xmb-detail-layout ${focused ? "psp-xmb-detail-layout--expanded" : ""} ${isPost ? "psp-xmb-detail-layout--writing" : ""} ${focused && isProject && images.length ? "psp-xmb-detail-layout--gallery" : ""}`}
            style={{ fontFamily: activeItem.fontFamily }}
          >
            <article className="psp-xmb-detail-inner min-w-0">
              {isProject || isPost ? (
                <>
                  {activeItem.date && (
                    <p className="psp-detail-date text-sm text-[var(--psp-accent)]">{activeItem.date}</p>
                  )}
                  <h2 className="psp-detail-title font-semibold leading-tight tracking-tight text-white">
                    {activeItem.title}
                  </h2>
                  {activeItem.description && (
                    <p className="psp-detail-description text-white/75">{activeItem.description}</p>
                  )}
                  {isProject && (activeItem.eyebrow || activeItem.note) && (
                    <p className="psp-detail-note text-sm text-white/50">
                      {[activeItem.eyebrow, activeItem.note].filter(Boolean).join(" · ")}
                    </p>
                  )}
                  {!focused && activeItem.detailHref && onActivate && (
                    <button
                      ref={openRef}
                      type="button"
                      onClick={onActivate}
                      className="psp-detail-open border-b border-[var(--psp-accent)] pb-1 text-sm font-medium text-white hover:text-[var(--psp-accent)] focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-[var(--psp-accent)]"
                    >
                      {isPost ? "Read" : "More info"} →
                    </button>
                  )}
                  <AnimatePresence initial={false}>
                    {focused && (
                      <motion.div
                        key={`additional-${activeItem.id}`}
                        initial={{ opacity: 0, y: reducedMotion ? 0 : 7 }}
                        animate={{ opacity: 1, y: 0 }}
                        exit={{ opacity: 0, y: 0, transition: { duration: reducedMotion ? 0 : 0.08 } }}
                        transition={{ ...animation, delay: reducedMotion ? 0 : 0.07 }}
                        className="psp-detail-extra"
                      >
                        {isPost && activeItem.image && (
                          <figure className="my-7 border-y border-white/10 py-4">
                            {/* eslint-disable-next-line @next/next/no-img-element */}
                            <img src={activeItem.image} alt={`${activeItem.title} illustration`} className="max-h-[30rem] w-full object-contain" />
                          </figure>
                        )}
                        {isPost && activeItem.tags && activeItem.tags.length > 0 && (
                          <div className="mt-7 flex flex-wrap gap-x-3 gap-y-2 text-xs text-white/45" aria-label="Writing topics">
                            {activeItem.tags.map((tag) => <span key={tag}>{tag}</span>)}
                          </div>
                        )}
                        {activeItem.body && (
                          <div className="mt-8 border-t border-white/15 pt-8">
                            <MarkdownText variant="body">{activeItem.body}</MarkdownText>
                          </div>
                        )}
                        {isProject && activeItem.highlights && activeItem.highlights.length > 0 && (
                          <section className="mt-9 border-t border-white/15 pt-7" aria-label="Project highlights">
                            <h3 className="mb-4 text-xs font-semibold uppercase tracking-[0.2em] text-white/45">Highlights</h3>
                            <ul className="space-y-3">
                              {activeItem.highlights.map((highlight) => (
                                <li key={highlight} className="border-l border-[var(--psp-accent)] pl-4 text-sm leading-6 text-white/70">
                                  {highlight}
                                </li>
                              ))}
                            </ul>
                          </section>
                        )}
                        {isProject && activeItem.tags && activeItem.tags.length > 0 && (
                          <div className="mt-8 flex flex-wrap gap-2" aria-label="Tools and technologies">
                            {activeItem.tags.map((tag) => (
                              <span key={tag} className="border border-white/15 px-3 py-1.5 text-xs text-white/60">{tag}</span>
                            ))}
                          </div>
                        )}
                        {isProject && links.length > 0 && (
                          <nav className="mt-9 flex flex-wrap gap-x-6 gap-y-3 border-t border-white/15 pt-7" aria-label="Project links">
                            {links.map((link, index) => (
                              <a
                                key={link.url + "-" + index}
                                href={link.url}
                                target="_blank"
                                rel="noopener noreferrer"
                                className="border-b border-[var(--psp-accent)] pb-1 text-sm text-white/80 hover:text-white focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--psp-accent)]"
                              >
                                {link.label} ↗
                              </a>
                            ))}
                          </nav>
                        )}
                      </motion.div>
                    )}
                  </AnimatePresence>
                </>
              ) : (
                <>
                  {activeItem.eyebrow && (
                    <p className="text-xs uppercase tracking-[0.2em] text-[var(--psp-accent)]">{activeItem.eyebrow}</p>
                  )}
                  <h2 className="text-2xl font-semibold tracking-tight text-white">{activeItem.title}</h2>
                  {activeItem.subtitle && <p className="text-sm font-medium text-white/70">{activeItem.subtitle}</p>}
                  <div className="my-3 h-px w-3/4 bg-white/20" />
                  {activeItem.description && <MarkdownText variant="preview">{activeItem.description}</MarkdownText>}
                  {activeItem.activationLabel && activeItem.href && activeItem.downloadName ? (
                    <a
                      href={activeItem.href}
                      download={activeItem.downloadName}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="mt-4 inline-flex w-fit items-center gap-2 rounded-full border border-white/15 bg-white/10 px-4 py-2 text-xs font-semibold text-white hover:bg-white/15"
                    >
                      ↓ {activeItem.activationLabel}
                    </a>
                  ) : activeItem.activationLabel && onActivate && (
                    <button type="button" onClick={onActivate} className="mt-4 rounded-full border border-white/15 bg-white/10 px-4 py-2 text-xs font-semibold text-white">
                      {activeItem.activationLabel}
                    </button>
                  )}
                  {activeItem.customContent}
                  {activeItem.highlights && activeItem.highlights.length > 0 && (
                    <ul className="mt-4 grid gap-2 text-xs leading-5 text-white/60" aria-label="Highlights">
                      {activeItem.highlights.slice(0, 2).map((highlight) => (
                        <li key={highlight} className="flex gap-2">
                          <span className="text-[var(--psp-accent)]" aria-hidden="true">◆</span>
                          <span>{highlight}</span>
                        </li>
                      ))}
                    </ul>
                  )}
                  {activeItem.tags && activeItem.tags.length > 0 && (
                    <div className="mt-4 flex flex-wrap gap-2">
                      {activeItem.tags.slice(0, 4).map((tag) => (
                        <span key={tag} className="rounded border border-white/10 bg-white/10 px-2 py-1 text-[11px] font-medium text-white/70">{tag}</span>
                      ))}
                    </div>
                  )}
                </>
              )}
            </article>
            <AnimatePresence initial={false}>
              {focused && isProject && images.length > 0 && (
                <motion.aside
                  key={`gallery-${activeItem.id}`}
                  className="psp-detail-gallery min-w-0"
                  aria-label="Project images"
                  initial={{ opacity: 0, x: reducedMotion ? 0 : 12 }}
                  animate={{ opacity: 1, x: 0 }}
                  exit={{ opacity: 0, transition: { duration: reducedMotion ? 0 : 0.08 } }}
                  transition={{ ...animation, delay: reducedMotion ? 0 : 0.07 }}
                >
                  <ProjectGallery key={activeItem.id} images={images} title={activeItem.title} variant="focus" />
                </motion.aside>
              )}
            </AnimatePresence>
          </div>
        )}
      </div>
    </section>
  );
}
